/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
uris=set()
for page in r.pages:
    for ref in page.get('/Annots',[]):
        a=ref.get_object().get('/A',{})
        if hasattr(a,'get_object'): a=a.get_object()
        if a.get('/URI'): uris.add(str(a['/URI']))
print('\\n'.join(sorted(uris)))
PY"
